    var piece = generateRandomPiece();
    pieces.push(piece);
    for (var row = 0; row < piece.length; row++) {
      for (var col = 0; col < piece[row].length; col++) {
        var block = document.createElement('div');
        if (piece[row][col] === 1) {
          block.style.backgroundColor = 'green';
        }
        pieceContainer.appendChild(block);
      }
    }
    pieceContainer.style.gridTemplateColumns = 'repeat(' + piece[0].length + ', 1fr)';
    pieceContainer.style.gridTemplateRows = 'repeat(' + piece.length + ', 1fr)';
  }
