function initializeGrid() {
  grid = [];
  var gameArea = document.getElementById('gameArea');
  gameArea.innerHTML = '';
  for (var i = 0; i < 8; i++) {
    var row = [];
    for (var j = 0; j < 8; j++) {
      row.push(0);
      var block = document.createElement('div');
      block.dataset.row = i;
      block.dataset.col = j;
      block.addEventListener('dragover', allowDrop);
      block.addEventListener('drop', drop);
      block.addEventListener('dragleave', removeHoverEffect);
      block.addEventListener('touchstart', touchStart);
      block.addEventListener('touchmove', touchMove);
      block.addEventListener('touchend', touchEnd);
      gameArea.appendChild(block);
    }
    grid.push(row);
  }
}

function generatePieces() {
  pieces = [];
  var piecesArea = document.getElementById('piecesArea');
  piecesArea.innerHTML = '';
  for (var i = 0; i < 3; i++) {
