  var pieceIndex = event.dataTransfer.getData('text');
  var block = event.target;
  placePiece(block, pieceIndex);
}

function placePiece(block, pieceIndex) {
  var row = parseInt(block.dataset.row);
  var col = parseInt(block.dataset.col);
  var piece = pieces[pieceIndex];

  if (canPlacePiece(row, col, piece)) {
    for (var i = 0; i < piece.length; i++) {
      for (var j = 0; j < piece[i].length; j++) {
        if (piece[i][j] === 1) {
          grid[row + i][col + j] = 1;
          var blockToColor = document.querySelector('[data-row="' + (row + i) + '"][data-col="' + (col + j) + '"]');
          blockToColor.style.backgroundColor = playerColor;
          score++;
        }
      }
    }
    pieces.splice(pieceIndex, 1);
    updatePiecesArea();
    checkForFullLines();
    if (pieces.length === 0) {
      generatePieces();
    }
    updateScoreDisplay();
    updateServer();
    updateLeaderboard();
  }
}

function highlightPlacement(block, pieceIndex) {
  var row = parseInt(block.dataset.row);
  var col = parseInt(block.dataset.col);
  var piece = pieces[pieceIndex];

  if (canPlacePiece(row, col, piece)) {
    for (var i = 0; i < piece.length; i++) {
      for (var j = 0; j < piece[i].length; j++) {
        if (piece[i][j] === 1) {
          var blockToHighlight = document.querySelector('[data-row="' + (row + i) + '"][data-col="' + (col + j) + '"]');
          blockToHighlight.classList.add('hover');
        }
      }
    }
  }
}

function removeHoverEffect(event) {
  var blocks = document.querySelectorAll('#gameArea div');
  blocks.forEach(function(block) {
    block.classList.remove('hover');
  });
}

function canPlacePiece(row, col, piece) {
  for (var i = 0; i < piece.length; i++) {
    for (var j = 0; j < piece[i].length; j++) {
      if (piece[i][j] === 1) {
        if (row + i >= 8 || col + j >= 8 || grid[row + i][col + j] === 1) {
          return false;
        }
      }
    }
  }
  return true;
}

function checkForFullLines() {
  for (var i = 0; i < 8; i++) {
    if (grid[i].every(val => val === 1)) {
      clearLine(i, 'row');
      score += 10;
    }
    if (grid.map(row => row[i]).every(val => val === 1)) {
      clearLine(i, 'col');
      score += 10;
    }
  }
}

function clearLine(index, type) {
  if (type === 'row') {
    for (var j = 0; j < 8; j++) {
      grid[index][j] = 0;
      var blockToClear = document.querySelector('[data-row="' + index + '"][data-col="' + j + '"]');
      blockToClear.style.backgroundColor = 'blue';
    }
  } else if (type === 'col') {
    for (var i = 0; i < 8; i++) {
      grid[i][index] = 0;
      var blockToClear = document.querySelector('[data-row="' + i + '"][data-col="' + index + '"]');
      blockToClear.style.backgroundColor = 'blue';
    }
