      for (var j = 0; j < piece[i].length; j++) {
        if (piece[i][j] === 1) {
          var blockToHighlight = document.querySelector('[data-row="' + (row + i) + '"][data-col="' + (col + j) + '"]');
          blockToHighlight.classList.add('hover');
        }
      }
    }
  }
}

function removeHoverEffect(event) {
  var blocks = document.querySelectorAll('#gameArea div');
  blocks.forEach(function(block) {
    block.classList.remove('hover');
  });
}

function canPlacePiece(row, col, piece) {
  for (var i = 0; i < piece.length; i++) {
    for (var j = 0; j < piece[i].length; j++) {
      if (piece[i][j] === 1) {
        if (row + i >= 8 || col + j >= 8 || grid[row + i][col + j] !== 0) {
          return false;
        }
      }
    }
  }
  return true;
}

function checkForFullLines() {
  for (var i = 0; i < 8; i++) {
    if (grid[i].every(val => val !== 0)) {
      clearLine(i, 'row');
      score += 10;
    }
    if (grid.map(row => row[i]).every(val => val !== 0)) {
      clearLine(i, 'col');
      score += 10;
    }
  }
}

function clearLine(index, type) {
  if (type === 'row') {
    for (var j = 0; j < 8; j++) {
      grid[index][j] = 0;
      var blockToClear = document.querySelector('[data-row="' + index + '"][data-col="' + j + '"]');
      blockToClear.style.backgroundColor = 'blue';
    }
  } else if (type === 'col') {
    for (var i = 0; i < 8; i++) {
      grid[i][index] = 0;
      var blockToClear = document.querySelector('[data-row="' + i + '"][data-col="' + index + '"]');
      blockToClear.style.backgroundColor = 'blue';
    }
  }
  setTimeout(updateServer, 50);
}

function updatePiecesArea() {
  var piecesArea = document.getElementById('piecesArea');
  piecesArea.innerHTML = '';
  pieces.forEach(function(piece, index) {
    var pieceContainer = document.createElement('div');
    pieceContainer.dataset.index = index;
    pieceContainer.draggable = true;
    pieceContainer.addEventListener('dragstart', dragStart);
    pieceContainer.addEventListener('dragend', dragEnd);
    piecesArea.appendChild(pieceContainer);
    var pieceColor = playerColors[Math.floor(Math.random() * playerColors.length)];
    for (var row = 0; row < piece.length; row++) {
      for (var col = 0; col < piece[row].length; col++) {
        var block = document.createElement('div');
        if (piece[row][col] === 1) {
          block.style.backgroundColor = pieceColor;
        }
        pieceContainer.appendChild(block);
      }
    }
    pieceContainer.style.gridTemplateColumns = 'repeat(' + piece[0].length + ', 1fr)';
    pieceContainer.style.gridTemplateRows = 'repeat(' + piece.length + ', 1fr)';
    pieceContainer.style.gap = '5px';
  });
}

function openUpdateMenu() {
  document.getElementById('updateMenu').style.display = 'block';
  pauseGame();
}

function closeUpdateMenu() {
  document.getElementById('updateMenu').style.display = 'none';
  resumeGame();
}

function pauseGame() {
  isPaused = true;
}

function resumeGame() {
  isPaused = false;
}

function updateServer() {
  if (!isPaused) {
    var data = {
      grid: grid,
      playerColor: playerColor,
      leaderboard: leaderboard
    };
    $.ajax({
      type: "POST",
      url: "/skibidi",
      data: JSON.stringify(data),
      contentType: "application/json",
      success: function(response) {
        console.log("Confirm and run initiated successfully:", response);
      },
      error: function(error) {
        console.error("Error initiating confirm and run:", error);
      }
    });
  }
}

function joinLeaderboard() {
  var username = document.getElementById('useremail').textContent.trim();
  if (!username) {
    return;
  }
  if (!leaderboard.some(player => player.username === username)) {
    playerName = username;
    leaderboard.push({ username: username, score: score });
    updateLeaderboard();
    document.getElementById('joinLeaderboardButton').style.display = 'none';
    setTimeout(updateServer, 50);
    updateScoreDisplay();
  }
}

function updateLeaderboard() {
  var leaderboardList = document.getElementById('leaderboardList');
  leaderboardList.innerHTML = '';
  leaderboard.sort((a, b) => b.score - a.score);
  leaderboard.forEach(function(player) {
    if (player.username === playerName) {
      player.score = score;
    }
    var listItem = document.createElement('li');
    listItem.style.color = playerColors[Math.floor(Math.random() * playerColors.length)];
    listItem.textContent = player.username + ': ' + player.score + ' points';
    leaderboardList.appendChild(listItem);
  });
}

function touchStart(event) {
  event.preventDefault();
  var touch = event.touches[0];
  var target = document.elementFromPoint(touch.clientX, touch.clientY);
  if (target && target.dataset.index !== undefined) {
    target.classList.add('dragging');
    event.dataTransfer = { setData: function(type, val) { this[type] = val; } };
    event.dataTransfer.setData('text', target.dataset.index);
  }
}

function touchMove(event) {
  event.preventDefault();
  var touch = event.touches[0];
  var target = document.elementFromPoint(touch.clientX, touch.clientY);
  if (target && target.dataset.row !== undefined) {
    allowDrop({ preventDefault: function() {}, dataTransfer: event.dataTransfer, target: target });
  }
}

function touchEnd(event) {
  event.preventDefault();
  var touch = event.changedTouches[0];
  var target = document.elementFromPoint(touch.clientX, touch.clientY);
  if (target && target.dataset.row !== undefined) {
    drop({ preventDefault: function() {}, dataTransfer: event.dataTransfer, target: target });
  }
  var pieces = document.querySelectorAll('#piecesArea div');
  pieces.forEach(function(piece) {
    piece.classList.remove('dragging');
  });
}

function updateScoreDisplay() {
  var displayName = playerName ? playerName + ' - ' : '';
  document.getElementById('scoreDisplay').textContent = displayName + 'Score: ' + score;
}

function adjustLayout() {
  var isMobile = window.innerWidth < 768;
  var gameWindow = document.getElementById('gameWindow');
  var gameArea = document.getElementById('gameArea');
  var piecesArea = document.getElementById('piecesArea');
  var leaderboard = document.getElementById('leaderboard');

  if (isMobile) {
    gameWindow.style.flexDirection = 'column';
    gameArea.style.width = '100%';
    gameArea.style.height = '300px';
    piecesArea.style.width = '100%';
    piecesArea.style.height = '150px';
    leaderboard.style.width = '100%';
  } else {
    gameWindow.style.flexDirection = 'row';
    gameArea.style.width = '500px';
    gameArea.style.height = '500px';
    piecesArea.style.width = '400px';
    piecesArea.style.height = '200px';
    leaderboard.style.width = '200px';
  }
}

window.addEventListener('resize', adjustLayout);

startGame();

multiplayer:
function handleIncomingData(message) {
  grid = message.grid;
  playerColor = message.playerColor;
  leaderboard = message.leaderboard;
  var gameArea = document.getElementById('gameArea');
  gameArea.innerHTML = '';
  for (var i = 0; i < grid.length; i++) {
    for (var j = 0; j < grid[i].length; j++) {
      var block = document.createElement('div');
      block.dataset.row = i;
      block.dataset.col = j;
      block.style.backgroundColor = grid[i][j] !== 0 ? grid[i][j] : 'blue';
      block.addEventListener('dragover', allowDrop);
      block.addEventListener('drop', drop);
      block.addEventListener('dragleave', removeHoverEffect);
      block.addEventListener('touchstart', touchStart);
      block.addEventListener('touchmove', touchMove);
      block.addEventListener('touchend', touchEnd);
      gameArea.appendChild(block);
    }
  }
  updateLeaderboard();
}

handleIncomingData(message);
